function ENGO531_Lab4_fix_right_wall_warmstart()
% ENGO 531 Lab 4: Align the INITIAL right-wall model to a converged
% Images 1-6 solution and use it for an Images 1-7 convergence trial.
%
% Inputs: six-image *_results.mat (generated by our previous script),
%         seven-image .tie/.ext/.pho/.int/.dis/.cfg and *_target_ID_map.csv
%         (generated by ENGO531_Lab4_select_images).
%
% This changes STARTING VALUES ONLY, never observed image coordinates.
% This tests one suspected cause; convergence is NOT guaranteed.
clc;
[fn,fd]=uigetfile('*_results.mat','Choose the CONVERGED Images 1-6 results MAT');
if isequal(fn,0),return;end
S=load(fullfile(fd,fn));
assert(all(isfield(S,{'names','numericID','XYZ0','eop','tie'})), ...
    'Six-image MAT is missing names, numericID, XYZ0, eop, or tie');
assert(isfield(S.eop,'XYZc') && isfield(S.eop,'wpk') && isfield(S.tie,'XYZ'), ...
    'Unexpected course output fields');

[fn7,fd7]=uigetfile('*.tie','Choose ORIGINAL Images 1-7 .tie from selectable-images script');
if isequal(fn7,0),return;end
oldPrefix=fullfile(fd7,fn7(1:end-4));
extensions={'.tie','.ext','.pho','.int','.dis','.cfg'};
for k=1:numel(extensions)
    assert(isfile([oldPrefix extensions{k}]),'Missing %s', [oldPrefix extensions{k}]);
end
mapFile=[oldPrefix '_target_ID_map.csv'];
assert(isfile(mapFile),'Missing target ID map: %s',mapFile);
map=readtable(mapFile,'TextType','string');
assert(all(ismember({'OriginalPointID','BundlePointID'},map.Properties.VariableNames)), ...
    'Unexpected ID map columns');

T0 = readmatrix([oldPrefix '.tie'], 'FileType', 'text');
E0=readmatrix([oldPrefix '.ext'], "FileType","text");
assert(size(T0,2)==4 && size(E0,2)==8,'Unexpected .tie/.ext structure');
assert(isequal(E0(:,1),(1:7)'), 'Expected images 1 through 7 in ascending order');

sixNames=string(S.names(:));
% The course solution tie.XYZ normally follows input .tie row order. Verify IDs
% if the returned object provides them; do not blindly assume if it disagrees.
assert(size(S.tie.XYZ,1)==numel(sixNames) && size(S.XYZ0,1)==numel(sixNames), ...
    'Six-image XYZ output has unexpected dimensions');
if isfield(S.tie,'ID')
    assert(isequal(double(S.tie.ID(:)),double(S.numericID(:))), ...
        'Adjusted tie IDs do not match six-image input order');
elseif isfield(S.tie,'id')
    assert(isequal(double(S.tie.id(:)),double(S.numericID(:))), ...
        'Adjusted tie IDs do not match six-image input order');
end

% Estimate rigid transform Xadj = R*Xinitial+t using common F points.
use=startsWith(sixNames,'F');
P=double(S.XYZ0(use,:)); Q=double(S.tie.XYZ(use,:));
assert(size(P,1)>=4,'Need four or more F points for alignment');
[p0,q0,R,t,rmsFit,fitVec]=rigidFit(P,Q);
fprintf('\nRigid alignment from %d front-wall targets:\n',size(P,1));
fprintf('RMS 3D target mismatch after alignment = %.2f mm\n',rmsFit);
fprintf('Median 3D mismatch = %.2f mm, maximum = %.2f mm\n',median(fitVec),max(fitVec));
fprintf('Rotation (degrees, rotation matrix applies to XYZ positions):\n');disp(R);
fprintf('Translation XYZ [mm]: %.2f %.2f %.2f\n',t);
if rmsFit>150
    warning(['The rigid alignment residual is large (%.0f mm). ', ...
        'The approximate front points are not a rigid match to the adjusted geometry. ', ...
        'Treat the right-wall transform as a rough starting approximation only.'],rmsFit);
end

% Original 7-image names in same row order as .tie file.
[tf,rowMap]=ismember(T0(:,1),double(map.BundlePointID));
assert(all(tf),'Some .tie IDs missing from target map');
sevenNames=string(map.OriginalPointID(rowMap));
Tnew=T0; Enew=E0;
right=startsWith(sevenNames,'R');
Tnew(right,2:4)=T0(right,2:4)*R' + t;

% Replace L/F starts with their own actual converged six-image tie solutions.
numReused=0;
for j=1:numel(sevenNames)
    if right(j),continue;end
    old=find(sixNames==sevenNames(j),1);
    if ~isempty(old)
        Tnew(j,2:4)=S.tie.XYZ(old,:);
        numReused=numReused+1;
    end
end
assert(size(S.eop.XYZc,1)==6 && size(S.eop.wpk,1)==6, ...
    'Expected six camera EOP records from reference solution');
Enew(1:6,3:5)=S.eop.XYZc;
Enew(1:6,6:8)=S.eop.wpk;
% For Image 7 position, use the SAME rigid coordinate transformation.
% Camera angles are intentionally NOT transformed; field-note rotations are
% retained until we establish compatible camera rotation-convention details.
Enew(7,3:5)=E0(7,3:5)*R' + t;
Enew(7,6:8)=E0(7,6:8);

fprintf('\nReused adjusted starting XYZ for %d L/F targets.\n',numReused);
fprintf('Transformed %d right-wall initial targets.\n',sum(right));
fprintf('Image 7 position original [mm] : %.2f %.2f %.2f\n',E0(7,3:5));
fprintf('Image 7 position aligned  [mm] : %.2f %.2f %.2f\n',Enew(7,3:5));
fprintf('Image 7 original omega/phi/kappa retained: %.2f %.2f %.2f deg\n',Enew(7,6:8));

% Report initial front-right geometric connection. F6 and R4 are nearby,
% but need not be exactly coincident (script assumed 65 mm X separation).
f6=find(sevenNames=='F6',1);r4=find(sevenNames=='R4',1);
if ~isempty(f6)&&~isempty(r4)
    fprintf('Original F6 - R4 separation: %.2f mm\n',norm(T0(f6,2:4)-T0(r4,2:4)));
    fprintf('New     F6 - R4 separation: %.2f mm\n',norm(Tnew(f6,2:4)-Tnew(r4,2:4)));
end

outPrefix=[oldPrefix '_aligned_warmstart'];
for k=1:numel(extensions)
    copyfile([oldPrefix extensions{k}],[outPrefix extensions{k}]);
end
writeRows([outPrefix '.tie'],Tnew,'%d %.6f %.6f %.6f\n');
writeRows([outPrefix '.ext'],Enew,'%d %d %.6f %.6f %.6f %.6f %.6f %.6f\n');

% Diagnostic tables are written BEFORE the adjustment so they're available
% even if the opaque course routine fails or diverges.
writetable(table(sevenNames,T0(:,2),T0(:,3),T0(:,4), ...
    Tnew(:,2),Tnew(:,3),Tnew(:,4), ...
    'VariableNames',{'Target','X0','Y0','Z0','Xstart','Ystart','Zstart'}), ...
    [outPrefix '_XYZ_comparison.csv']);
writetable(table(E0(:,1),E0(:,3),E0(:,4),E0(:,5),Enew(:,3),Enew(:,4),Enew(:,5), ...
    'VariableNames',{'Image','OldX','OldY','OldZ','NewX','NewY','NewZ'}), ...
    [outPrefix '_EOP_comparison.csv']);

fprintf('\nCreated: %s.*\n',outPrefix);
fprintf('Review _XYZ_comparison.csv before interpreting adjustment output.\n');
reply=input('Run course bundle using these INITIAL approximations? [y/N]: ','s');
if ~strcmpi(strtrim(reply),'y')
    fprintf('Adjustment not run. Input files are saved.\n');return;
end
assert(exist('full_matlab_bundle','file')==2 || exist('full_matlab_bundle','file')==6, ...
    'Add full_matlab_bundle.p to the MATLAB path');
[eop,iop,con,tie,Cx,vr_img,vr_eop,vr_dis,vr_con]=full_matlab_bundle(outPrefix);
if ~isempty(vr_img)
    fprintf('Returned residual RMS = %.3f px (valid ONLY if course reports convergence)\n', ...
        sqrt(mean(vr_img(:,1).^2)));
end
fprintf('Returned camera XYZ [mm] (ignore if adjustment diverges):\n');disp(eop.XYZc);
save([outPrefix '_results.mat'],'eop','iop','con','tie','Cx','vr_img', ...
    'vr_eop','vr_dis','vr_con','R','t','rmsFit','Enew','Tnew','sevenNames');
fprintf('Check whether MATLAB explicitly printed Adjustment converged.\n');
end

function [p0,q0,R,t,rmsFit,fitVec]=rigidFit(P,Q)
p0=mean(P,1);q0=mean(Q,1);
A=P-p0;B=Q-q0;
[U,~,V]=svd(A'*B);
D=diag([1 1 det(V*U')]);
R=V*D*U';
t=q0-p0*R';
Dxyz=P*R'+t-Q;
fitVec=sqrt(sum(Dxyz.^2,2));
rmsFit=sqrt(mean(fitVec.^2));
end

function writeRows(path,A,fmt)
f=fopen(path,'w');assert(f>=0,'Cannot write: %s',path);
c=onCleanup(@()fclose(f));
for j=1:size(A,1)
    fprintf(f,fmt,A(j,:));
end
end
